"""Conway's Game of Life with every generation computed on the GPU via wgpu."""

import sys

import numpy as np
import wgpu

WORKGROUP = 8

SHADER = f"""
struct Params {{
    width: u32,
    height: u32,
}};

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read> src: array<u32>;
@group(0) @binding(2) var<storage, read_write> dst: array<u32>;

fn cell(x: i32, y: i32) -> u32 {{
    if (x < 0 || y < 0 || x >= i32(params.width) || y >= i32(params.height)) {{
        return 0u;
    }}
    return src[u32(y) * params.width + u32(x)];
}}

@compute @workgroup_size({WORKGROUP}, {WORKGROUP})
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {{
    if (gid.x >= params.width || gid.y >= params.height) {{
        return;
    }}
    let x = i32(gid.x);
    let y = i32(gid.y);
    let n = cell(x - 1, y - 1) + cell(x, y - 1) + cell(x + 1, y - 1)
          + cell(x - 1, y)                      + cell(x + 1, y)
          + cell(x - 1, y + 1) + cell(x, y + 1) + cell(x + 1, y + 1);
    let alive = src[gid.y * params.width + gid.x];
    var next = 0u;
    if (n == 3u || (alive == 1u && n == 2u)) {{
        next = 1u;
    }}
    dst[gid.y * params.width + gid.x] = next;
}}
"""


def parse(text):
    tokens = text.split()
    if len(tokens) < 3:
        raise ValueError("missing header")
    width, height, generations = (int(t) for t in tokens[:3])
    if not (1 <= width <= 512 and 1 <= height <= 512 and 0 <= generations <= 1000):
        raise ValueError("header out of range")
    cells = tokens[3:]
    if len(cells) != width * height:
        raise ValueError(f"expected {width * height} cells, got {len(cells)}")
    if any(c not in ("0", "1") for c in cells):
        raise ValueError("cells must be 0 or 1")
    grid = np.array([c == "1" for c in cells], dtype=np.uint32).reshape(height, width)
    return width, height, generations, grid


def run_gpu(grid, generations):
    height, width = grid.shape
    if generations == 0:
        return grid.copy()

    adapter = wgpu.gpu.request_adapter_sync(power_preference="high-performance")
    device = adapter.request_device_sync()

    size = grid.nbytes
    usage = wgpu.BufferUsage.STORAGE | wgpu.BufferUsage.COPY_SRC | wgpu.BufferUsage.COPY_DST
    buffers = [device.create_buffer(size=size, usage=usage) for _ in range(2)]
    device.queue.write_buffer(buffers[0], 0, np.ascontiguousarray(grid).tobytes())

    params = device.create_buffer_with_data(
        data=np.array([width, height, 0, 0], dtype=np.uint32).tobytes(),
        usage=wgpu.BufferUsage.UNIFORM,
    )

    module = device.create_shader_module(code=SHADER)
    pipeline = device.create_compute_pipeline(
        layout="auto", compute={"module": module, "entry_point": "main"}
    )
    layout = pipeline.get_bind_group_layout(0)

    def bind_group(src, dst):
        return device.create_bind_group(
            layout=layout,
            entries=[
                {"binding": 0, "resource": {"buffer": params, "offset": 0, "size": params.size}},
                {"binding": 1, "resource": {"buffer": src, "offset": 0, "size": size}},
                {"binding": 2, "resource": {"buffer": dst, "offset": 0, "size": size}},
            ],
        )

    groups = [bind_group(buffers[0], buffers[1]), bind_group(buffers[1], buffers[0])]
    gx = (width + WORKGROUP - 1) // WORKGROUP
    gy = (height + WORKGROUP - 1) // WORKGROUP

    encoder = device.create_command_encoder()
    for gen in range(generations):
        # Separate passes guarantee each generation sees the complete previous one.
        compute = encoder.begin_compute_pass()
        compute.set_pipeline(pipeline)
        compute.set_bind_group(0, groups[gen % 2])
        compute.dispatch_workgroups(gx, gy, 1)
        compute.end()
    device.queue.submit([encoder.finish()])

    result = buffers[generations % 2]
    data = device.queue.read_buffer(result)
    return np.frombuffer(data, dtype=np.uint32).reshape(height, width).copy()


def main(argv):
    if len(argv) < 2:
        print("usage: main.py <input-file>", file=sys.stderr)
        return 2
    with open(argv[1], "r") as f:
        width, height, generations, grid = parse(f.read())
    final = run_gpu(grid, generations)
    lines = [" ".join("1" if v else "0" for v in row) for row in final]
    lines.append(f"ALIVE {int(np.count_nonzero(final))}")
    sys.stdout.write("\n".join(lines) + "\n")
    sys.stdout.flush()
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

